export function Reusability({
  badgeText = "{{badgeText}}",
  context = "{{context}}",
  accent = "{{accent}}",
  bold = {{bold}},
}) {
  const Badge = () => <span style={{ fontSize: 11, padding: "3px 9px", borderRadius: 999, color: "#241430", fontWeight: bold ? 700 : 400, background: accent }}>{badgeText}</span>;
  const ctxStyle = { display: "flex", alignItems: "center", justifyContent: "space-between", padding: 12, borderRadius: 8, background: "#ffffff", border: "1.5px solid #24143018" };
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontSize: 11, color: "#24143099" }}>The same &lt;Badge&gt; component, unchanged, reused in three places</p>
      {context === "nav" && <div style={ctxStyle}>Dashboard <Badge /></div>}
      {context === "card" && <div style={ctxStyle}><strong>Analytics module</strong><Badge /></div>}
      {context === "table" && <div style={ctxStyle}>Row: Export tool <Badge /></div>}
    </div>
  );
}
